presetParts.presetInit:
n = -5000; loop (20000, megabuf(n)=0; gmegabuf(n)=0; n +=1; );

MINBPM = 40; MAXBPM = 180; num_res = 80; num_sig=3;
blocksize = num_res*12+12; 
reg04 = blocksize;

sig = 0;
loop (num_sig,
  index = 0;
  loop (num_res,
    n = blocksize*sig + 12*index;
    BPM      = minbpm * pow(maxbpm/minbpm,index/num_res);
    gmegabuf(n) = BPM;
    index += 1;
  );
sig+=1);

pi = 3.1416;
OCTAVE = (num_res) * log(2) / log (MAXBPM / MINBPM);

prog = 0;
bindex = rand(8);
count5 = rand(8);

presetParts.perFrame:
dt = min (1/fps,0.1) ; //Stability !
dec_f = 0.8; dec_m = 1 - 4*dt; dec_s = 1 - dt;

beat = max (max (bass, mid), treb); 
avg = avg*dec_s + beat*(1-dec_s);
is_beat = above(beat, .5+avg+peak) * above (time, t0+.25);
t0 = is_beat*time + (1-is_beat)*t0;
peak = is_beat * beat + (1-is_beat)*peak*dec_m;
bindex = (bindex + is_beat) %8;
q24 = is_beat;
q27 = bindex;

sig=0; 
loop (num_sig,
  excite = if (sig==0, bass-bass_att, if (sig==1, mid-mid_att, treb-treb_att));
  index = 0; maxquad = 0;
  m = sig*blocksize+num_res*12; // Start Infoblock;
  gmegabuf(m+2) = 0.001; //lok. MW
  gmegabuf(m+3) = 0; //lok. MAX
  loop (num_res, 
    n = sig*blocksize+index*12;  omega=gmegabuf(n) * 6.283/60;
    gmegabuf (n+1) *= 1- 0.22*dt; 
    EC_Steps = 4; dt1 = dt/EC_Steps;
    ex = excite / sqrt(omega);
    loop (EC_Steps, // Euler-Cauchy 
      gmegabuf (n+1) += (ex - sqr(omega)*gmegabuf(n+2)) * dt1;
      gmegabuf (n+2) += gmegabuf(n+1) * dt1);
    beatcos  = gmegabuf(n+1);  beatsin = gmegabuf(n+2)*omega;
    quad     = sqrt (pow(beatsin,2) + pow(beatcos,2)) ;
    gmegabuf (m+4) += abs (gmegabuf(n+3)-Quad); //Lok Aenderung
    gmegabuf (n+3) = gmegabuf(n+3) *dec_m +  quad* (1-dec_m);
    if (gmegabuf(n+3) > gmegabuf(m+3),gmegabuf(m+3)=gmegabuf(n+3),0); //LOK MAX
    gmegabuf (m+2) += gmegabuf(n+3)/num_res; //LOK MW
    gmegabuf(n+4)= beatcos;
    gmegabuf(n+5)= beatsin;
  index += 1;);
sig+=1;);


//Beste raussuchen
sig = 0; quali = 0; bestsig = -1;
loop (num_sig,
  m = sig*blocksize+num_res*12; // Start Infoblock;
  tmp = gmegabuf(m+3)/gmegabuf(m+2) ;
  if (tmp > quali, quali = tmp; bestsig = sig;, 0);
sig += 1);

index = 0; maxind1 = 0; maxv *= dec_s;
loop (num_res, 
  n = bestsig*blocksize+index*12; // Start Infoblock;
